//! Subcommand registry (card 1.A3).
//!
//! # FROZEN INTERFACE
//!
//! This module and `main.rs` are **FROZEN after card 1.A3**. Later cards
//! implement their subcommand by editing ONLY the stub module listed for
//! their card below — do not edit this file, `main.rs`, or another card's
//! module (AGENTS.md §3.7; adding a new subcommand needs Lead-granted
//! temporary ownership of the frozen files).
//!
//! # Ownership map
//!
//! | Module                   | Subcommand           | Owning card |
//! |--------------------------|----------------------|-------------|
//! | `cmd::gate`              | `gate`               | 1.A3 (implemented) |
//! | `cmd::schema_gen`        | `schema-gen`         | 1.B2 |
//! | `cmd::tokens`            | `tokens`             | 1.B4 |
//! | `cmd::codegen`           | `codegen`            | 1.D4 |
//! | `cmd::check_architecture`| `check-architecture` | 1.E1 |
//! | `cmd::rebrand`           | `rebrand`            | 1.E4 |

use std::process::ExitCode;

use crate::XtaskError;

pub mod check_architecture;
pub mod codegen;
pub mod gate;
pub mod rebrand;
pub mod schema_gen;
pub mod tokens;

/// One registered subcommand: name, owning card, help text and entry point.
pub struct Subcommand {
    /// Name typed after `cargo xtask`.
    pub name: &'static str,
    /// Owning card in `docs/13-agent-wave-program.md`.
    pub card: &'static str,
    /// One-line summary for `cargo xtask help`.
    pub summary: &'static str,
    /// Whether the owning card has landed (drives the help status label).
    pub implemented: bool,
    /// Entry point; receives the args after the subcommand name.
    pub run: fn(&[String]) -> Result<ExitCode, XtaskError>,
}

/// The full subcommand table (extension-first: every wave-1 consumer of
/// xtask is registered here from day one, dispatching to stub modules).
pub const SUBCOMMANDS: &[Subcommand] = &[
    Subcommand {
        name: "gate",
        card: "1.A3",
        summary: "Local quality gate: doc 10 §2 command table + honest report",
        implemented: true,
        run: gate::run,
    },
    Subcommand {
        name: "schema-gen",
        card: "1.B2",
        summary: "Settings-schema generators (doc 07 §5)",
        implemented: false,
        run: schema_gen::run,
    },
    Subcommand {
        name: "tokens",
        card: "1.B4",
        summary: "Theme-token pipeline (doc 08 §3)",
        implemented: false,
        run: tokens::run,
    },
    Subcommand {
        name: "codegen",
        card: "1.D4",
        summary: "Command-catalog codegen (doc 05 §2-3)",
        implemented: false,
        run: codegen::run,
    },
    Subcommand {
        name: "check-architecture",
        card: "1.E1",
        summary: "Architecture boundary checks (doc 01 §5)",
        implemented: false,
        run: check_architecture::run,
    },
    Subcommand {
        name: "rebrand",
        card: "1.E4",
        summary: "Rebrand tooling (doc 07 §8)",
        implemented: false,
        run: rebrand::run,
    },
];

/// Find a registered subcommand by exact name.
pub fn lookup(name: &str) -> Option<&'static Subcommand> {
    SUBCOMMANDS.iter().find(|sub| sub.name == name)
}

/// All subcommand names, for usage messages.
pub fn names() -> Vec<&'static str> {
    SUBCOMMANDS.iter().map(|sub| sub.name).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_names_are_unique() {
        let names = names();
        let mut sorted = names.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(names.len(), sorted.len(), "duplicate subcommand name");
    }

    #[test]
    fn registry_contains_all_wave1_subcommands() {
        for expected in [
            "gate",
            "schema-gen",
            "tokens",
            "codegen",
            "check-architecture",
            "rebrand",
        ] {
            assert!(
                lookup(expected).is_some(),
                "subcommand `{expected}` missing from the frozen registry"
            );
        }
    }

    #[test]
    fn only_gate_is_implemented_in_v0() {
        for sub in SUBCOMMANDS {
            assert_eq!(
                sub.implemented,
                sub.name == "gate",
                "unexpected implemented flag for `{}`",
                sub.name
            );
        }
    }
}
